#!/usr/bin/env python3
"""Minimal stdio MCP client for the ft2 (FastTracker II) server."""
import json, subprocess, os, sys, base64, time, queue, threading, math

class FT2Client:
    def __init__(self, cwd="/workspace", timeout=30):
        self.timeout = timeout
        self.ident = 0
        self.replies = queue.Queue()
        self.errors = []
        home = os.path.join(cwd, "isolated-home")
        os.makedirs(home, exist_ok=True)
        env = os.environ.copy()
        env.setdefault("SDL_AUDIODRIVER", "dummy")
        env.update(HOME=home, XDG_CONFIG_HOME=os.path.join(home, ".config"))
        self.proc = subprocess.Popen(
            ["ft2"], cwd=cwd, env=env, stdin=subprocess.PIPE,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            text=True, encoding="utf-8", errors="strict", bufsize=1,
        )
        for stream, is_stdout in [(self.proc.stdout, True), (self.proc.stderr, False)]:
            threading.Thread(target=self._read, args=(stream, is_stdout), daemon=True).start()
        self.initialize()

    def _read(self, stream, stdout):
        try:
            for line in stream:
                if not line:
                    break
                if stdout:
                    try:
                        self.replies.put(json.loads(line))
                    except Exception:
                        self.replies.put({"jsonrpc": "2.0", "id": self.ident, "error": {"message": "parse error"}})
                else:
                    self.errors.append(line.rstrip())
        except Exception as exc:
            self.replies.put({"error": str(exc)})
        self.replies.put(None)

    def initialize(self):
        self.request("initialize", {"protocolVersion": "2024-11-05", "capabilities": {},
                                    "clientInfo": {"name": "composer", "version": "1.0"}})
        self.request("notifications/initialized", {})

    def request(self, method, params):
        self.ident += 1
        msg = {"jsonrpc": "2.0", "id": self.ident, "method": method, "params": params}
        self.proc.stdin.write(json.dumps(msg, ensure_ascii=True) + "\n")
        self.proc.stdin.flush()
        deadline = time.monotonic() + self.timeout
        while True:
            try:
                reply = self.replies.get(timeout=max(0, deadline - time.monotonic()))
            except queue.Empty:
                raise RuntimeError(f"timeout awaiting {method}")
            if isinstance(reply, Exception):
                raise reply
            if reply is None:
                raise RuntimeError("server exited: " + " | ".join(self.errors))
            if reply.get("id") == self.ident:
                if "error" in reply:
                    raise RuntimeError(f"RPC error: {reply['error']}")
                return reply.get("result", {})
            # forward notifications
            if "method" in reply and reply.get("id") is None:
                continue

    def call(self, tool, **arguments):
        result = self.request("tools/call", {"name": tool, "arguments": arguments})
        if isinstance(result, dict) and result.get("isError"):
            raise RuntimeError(result.get("message", "tool failed"))
        return result

    def close(self):
        try:
            self.proc.stdin.close()
            self.proc.wait(timeout=2)
        except Exception:
            self.proc.kill()
        for t in self.proc.thread_stubs if False else []:
            pass

if __name__ == "__main__":
    c = FT2Client()
    print("connected")
    c.close()
EOF
