        self.errors = []
        home = os.path.join(cwd, "isolated-home")
        os.makedirs(home, exist_ok=True)
        env = os.environ.copy()
        env.setdefault("SDL_AUDIODRIVER", "dummy")
        env.update(HOME=home, XDG_CONFIG_HOME=os.path.join(home, ".config"))
        self.proc = subprocess.Popen(
            ["/usr/local/bin/ft2-clone", "--mcp"], cwd=cwd, env=env,
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            text=True, encoding="utf-8", errors="strict", bufsize=1,
        )
        for stream, is_stdout in [(self.proc.stdout, True), (self.proc.stderr, False)]:
            threading.Thread(target=self._read, args=(stream, is_stdout), daemon=True).start()
        self.initialize()

    def _read(self, stream, stdout):
        try:
            for line in stream:
                if not line:
                    break
                if stdout:
                    try:
                        self.replies.put(json.loads(line))
                    except Exception as exc:
                        self.replies.put({"jsonrpc": "2.0", "id": self.ident, "error": repr(exc)})
                else:
                    self.errors.append(line.rstrip())
        except Exception as exc:
            self.replies.put({"error": str(exc)})
        self.replies.put(None)

