        self.ident += 1
        msg = {"jsonrpc": "2.0", "id": self.ident, "method": method, "params": params}
        self.proc.stdin.write(json.dumps(msg, ensure_ascii=True) + "\n")
        self.proc.stdin.flush()
        deadline = time.monotonic() + self.timeout
        while True:
            try:
                reply = self.replies.get(timeout=max(0, deadline - time.monotonic()))
            except queue.Empty:
